using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace LoopPedal { static class ResamplingChecks {
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
 static Engine Bank(int bank){var e=new Engine();float[] a=new float[24000*2];for(int i=0;i<24000;i++){a[2*i]=(float)(.08*Math.Sin(i*(bank==0?.031:.047)));a[2*i+1]=(float)(.06*Math.Cos(i*(bank==0?.027:.039)));}e.Layers.Add(new Layer{Name="Source",Original=a,Audio=a});e.LoopFrames=24000;e.Fx.Delay=.25f;e.Fx.Reverb=.2f;e.Fx.Filter=bank==0?-.15f:.12f;return e;}
 static float[] PadTake(float[] a){var result=new float[48000];Array.Copy(a,result,a.Length);int fade=Math.Min(240,a.Length/2);for(int i=0;i<fade;i++){float gain=(float)(.5-.5*Math.Cos(Math.PI*i/fade));int p=a.Length-2-i*2;result[p]*=gain;result[p+1]*=gain;}return result;}
 static void Render(Engine e,float[] dry,float[] post,int frames){e.Mix(new float[frames*2],frames,dry,false);for(int i=0;i<frames;i++){float l,r,fl,fr;e.Fx.Process(dry[2*i],dry[2*i+1],out l,out r);e.Fx.FilterOutput(dry[2*i]+l,dry[2*i+1]+r,out fl,out fr);post[2*i]=fl;post[2*i+1]=fr;}}
 static void TriggerAndAuto(){
 using(var e=Bank(0)){e.InputMode=5;e.WaitForInput=true;e.TriggerDb=-60;var provider=new LoopProvider(e);e.Begin(true);provider.Read(new byte[1024*8],0,1024*8);Check(!e.WaitingForInput&&e.CapturedFrames>0,"self post-FX did not trigger without hardware");long at=e.RecordStartAudio;e.Finish(false);Check(e.Layers.Last().Offset==at,"internal trigger onset phase");}
 using(var e=new Engine()){e.InputMode=5;e.WaitForInput=true;var hardware=new Input(new SourceChoice{Name="Unselected live",Left=0,Right=1});e.Inputs.Add(hardware);e.SetInputMonitor(true);e.Begin(false);hardware.Feed(Enumerable.Repeat(.5f,2048).ToArray(),2048,2,0);var provider=new LoopProvider(e);var output=new byte[1024*8];provider.Read(output,0,output.Length);Check(e.WaitingForInput&&e.CapturedFrames==0,"hardware/monitor triggered internal-only capture");e.Finish(false);}
 using(var e=Bank(0)){e.InputMode=5;e.AutoOverdub=true;e.Begin(true);var provider=new LoopProvider(e);var output=new byte[480*8];for(int i=0;i<100;i++){provider.Read(output,0,output.Length);e.DrainCompletedPasses();}Check(e.Recording&&e.Layers.Count==3,"automatic self-resampling passes");e.Finish(false);}
 }
 public static void Run(){var log=new List<string>();try{TriggerAndAuto();log.Add("PASS internal-only trigger phase; unselected live/monitor isolation; automatic Self post-FX passes");for(int bank=0;bank<2;bank++)for(int mode=1;mode<9;mode++)foreach(bool destructive in new[]{false,true}){
 using(var a=Bank(0))using(var b=Bank(1))using(var ra=Bank(0))using(var rb=Bank(1)){
 a.Partner=b;a.QuantizePeer=b;b.QuantizePeer=a;b.ClockLeader=a;a.Fx.CopySharedSettingsTo(b.Fx);ra.Fx.CopySharedSettingsTo(rb.Fx);
 var target=bank==0?a:b;target.InputMode=mode;target.Destructive=destructive;target.ClickDuringRecord=true;bool live=SourceRouting.UsesLive(mode);if(live)target.Inputs.Add(new Input(new SourceChoice{Name="Live",Left=0,Right=1}));
 var provider=new LoopProvider(a);const int frames=1024;var bytes=new byte[frames*8];var da=new float[frames*2];var db=new float[frames*2];var pa=new float[frames*2];var pb=new float[frames*2];var input=Enumerable.Repeat(.025f,frames*2).ToArray();
 provider.Read(bytes,0,bytes.Length);Render(ra,da,pa,frames);Render(rb,db,pb,frames);target.Begin(false);var expected=new List<float>();
 for(int block=0;block<4;block++){if(live)target.Inputs[0].Feed(input,input.Length,2,target.AudioFrame);provider.Read(bytes,0,bytes.Length);Render(ra,da,pa,frames);Render(rb,db,pb,frames);float[] src=mode<=2?(bank==0?db:da):mode<=4?(bank==0?pb:pa):(bank==0?pa:pb);for(int i=0;i<frames*2;i++)expected.Add(mode>=7?pa[i]+pb[i]:src[i]);}
 target.Finish(false);double error=0;
 if(destructive){using(var oracle=Bank(bank)){oracle.Destructive=true;var expectedAudio=PadTake(expected.ToArray());oracle.CommitLayer(new Layer{Name="Expected",Original=expectedAudio,Audio=expectedAudio,Offset=1024});Check(target.Layers.Count==1,"destructive layer count");if(live){var liveAudio=PadTake(Enumerable.Repeat(.025f,8192).ToArray());oracle.CommitLayer(new Layer{Name="Live",Original=liveAudio,Audio=liveAudio,Offset=1024});}
 for(int i=0;i<oracle.Layers[0].Audio.Length;i++)error=Math.Max(error,Math.Abs(target.Layers[0].Audio[i]-oracle.Layers[0].Audio[i]));Check(error<1e-6,"destructive source/sum error "+error);
 }}else{Check(target.Layers.Count==(live?3:2),"separate live/internal layers");var captured=target.Layers.Last();Check(captured.Offset==1024,"capture phase");for(int i=0;i<expected.Count;i++)error=Math.Max(error,Math.Abs(captured.Original[i]-expected[i]));Check(error<1e-6,"post-FX capture error "+error+" bank="+bank+" mode="+mode);if(live)Check(target.Layers[1].Original.All(x=>x==.025f),"live layer changed");}
 log.Add("PASS bank="+bank+" source="+mode+" destructive="+destructive+" stereo error="+error+" phase=1024; internal capture excludes recording click");
 }}File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"resampling-tests.txt"),log);}catch(Exception e){log.Add("FAIL "+e);File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"resampling-tests.txt"),log);Environment.ExitCode=1;}}
} }

namespace LoopPedal { partial class Pedal {
 public void VerifyResamplingUi(){SetSingleMode(false);for(int bank=0;bank<2;bank++)for(int mode=0;mode<9;mode++){ShowBankMenu(bank,recPads[bank]);var input=currentPopup.Items.Cast<System.Windows.Forms.ToolStripMenuItem>().Single(x=>x.Text=="Input");if(input.DropDownItems.Count!=10)throw new Exception("Nine sources + audio devices");var item=(System.Windows.Forms.ToolStripMenuItem)input.DropDownItems[mode];if(item.Text!=SourceRouting.Label(bank,mode)||!item.Enabled)throw new Exception("Source menu label/availability");item.PerformClick();if(loopers[bank].InputMode!=mode)throw new Exception("Source selection failed");currentPopup.Close();}SetSingleMode(true);ShowBankMenu(0,recPads[0]);var sources=currentPopup.Items.Cast<System.Windows.Forms.ToolStripMenuItem>().Single(x=>x.Text=="Input");for(int i=0;i<9;i++)if(sources.DropDownItems[i].Enabled==SourceRouting.Other(i))throw new Exception("Single source guard");currentPopup.Close();}
} }
